import base64
import hashlib
import json
import unittest
from urllib.parse import parse_qs

from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding

import app_crypto as crypto


# Independently generated by JDK 21 javax.crypto.Cipher and java.security.Signature
# following shipped vk.h1.c, vk.e.h, vk.l.J/I. The same RSA mathematical key was
# normalized to PKCS8 for the JDK parser; no key material is embedded in tests.
# Reproducible local oracle: evidence/offline-dex/crypto-oracle/AppCryptoOracle.java
PLAIN = '{"cellPhone":"test-phone","pin":"0000"}'
PAYLOAD = {"cellPhone": "test-phone", "pin": "0000"}
NONCE = "0123456789ABCDEFGHIJKLMNOPQRSTUV"
TRANSPORT_ORACLE = "Xe7B5LOYV/MDGzU79NnwRH2n7/Pzz8IG28eWPu4NR+lz7Q98gh1EEPJ8FjCf0Gya"
LOGIN_ORACLE_B64 = "YldmemFSbnJJTGZUbnZUZFB6UHdSaFhaTVczTjlXSnBsOGJvLzh5QktVd2VKaDdLR3hjUENjU0ZlVjRmVnF6ego="
SIGNATURE_ORACLE_SHA256 = "4f22a4d3c6555953e5c991c39de9e5b4d3d214bd4ca953aa0c19204cbb359afc"


class AppCryptoTests(unittest.TestCase):
    def test_local_config_is_usable(self):
        self.assertTrue(crypto.is_ready())

    def test_transport_cipher_matches_independent_java_oracle(self):
        self.assertEqual(crypto.encrypt_text(PLAIN), TRANSPORT_ORACLE)
        self.assertEqual(crypto.decrypt_text(TRANSPORT_ORACLE), PLAIN)

    def test_login_cipher_includes_android_default_linefeed(self):
        expected = base64.b64decode(LOGIN_ORACLE_B64).decode("ascii")
        self.assertEqual(crypto.encrypt_login_form(PAYLOAD), expected)
        self.assertEqual(crypto.decrypt_login_form(expected), PLAIN)
        self.assertTrue(expected.endswith("\n"))

    def test_signature_matches_independent_java_oracle(self):
        signature = crypto.sign_request("/app-bff-api/sms/send", PLAIN, nonce=NONCE)
        self.assertTrue(signature.startswith("version=1,channel=02103001,nonce=" + NONCE + ",sign="))
        encoded_signature = signature.split(",sign=", 1)[1]
        self.assertEqual(hashlib.sha256(encoded_signature.encode()).hexdigest(), SIGNATURE_ORACLE_SHA256)

    def test_sms_signs_plaintext_before_transport_wrapper(self):
        wire, headers = crypto.build_request("POST", "/app-bff-api/sms/send", PAYLOAD, nonce=NONCE)
        self.assertEqual(json.loads(wire), {"encrypted": TRANSPORT_ORACLE})
        self.assertEqual(headers["x-data-track"], "2")
        self.assertEqual(headers["x-signature"], crypto.sign_request("/app-bff-api/sms/send", PLAIN, nonce=NONCE))
        raw = base64.b64decode(headers["x-signature"].split(",sign=", 1)[1])
        crypto._signing_key().public_key().verify(
            raw, crypto.signature_message("/app-bff-api/sms/send", PLAIN, nonce=NONCE).encode(),
            padding.PKCS1v15(), hashes.SHA256())

    def test_login_bypasses_outer_encryption_and_signs_exact_form(self):
        wire, headers = crypto.build_request("POST", "/app-bff-api/login", PAYLOAD, form=True, nonce=NONCE)
        self.assertNotIn("x-data-track", headers)
        self.assertIn(b"%0A", wire)
        self.assertEqual(parse_qs(wire.decode())["body"][0], crypto.encrypt_login_form(PAYLOAD))
        self.assertEqual(headers["x-signature"], crypto.sign_request("/app-bff-api/login", wire, nonce=NONCE))

    def test_ccms_switch_can_disable_transport_encryption(self):
        wire, headers = crypto.build_request("POST", "/app-bff-api/sms/send", PAYLOAD, encrypt=False, nonce=NONCE)
        self.assertEqual(wire.decode(), PLAIN)
        self.assertNotIn("x-data-track", headers)

    def test_default_body_interceptor_supplies_empty_json_object(self):
        wire, _ = crypto.build_request("POST", "/app-bff-api/sms/send", nonce=NONCE)
        self.assertEqual(crypto.decrypt_text(json.loads(wire)["encrypted"]), "{}")

    def test_query_canonicalization_sorts_and_retains_last_value(self):
        self.assertEqual(crypto.canonical_query("/x?z=first&a=1&z=last%20value&flag"), "a=1&flag=null&z=last value")
        wire, headers = crypto.build_request("GET", "/x?z=first&a=1&z=last", nonce=NONCE)
        cipher = parse_qs(wire.decode())["encrypted"][0]
        self.assertEqual(json.loads(crypto.decrypt_text(cipher)), {"z": "last", "a": "1"})
        self.assertEqual(headers["x-signature"], crypto.sign_request("/x?z=first&a=1&z=last", "", nonce=NONCE))

    def test_response_decryption_preserves_plaintext_error_responses(self):
        self.assertEqual(crypto.decode_response(TRANSPORT_ORACLE, {"X-Data-Track": "2"}), PAYLOAD)
        self.assertEqual(crypto.decode_response('{"success":false}', {"x-data-track": "2"}), {"success": False})
        self.assertEqual(crypto.decode_response(TRANSPORT_ORACLE, {"x-data-track": "3"}), TRANSPORT_ORACLE)
        self.assertEqual(crypto.decode_response("gateway unavailable", encrypted=True), "gateway unavailable")

    def test_gson_defaults_omit_object_nulls_and_escape_html(self):
        self.assertEqual(crypto.compact_json({"x": None, "y": [None, "<&='\u2028"]}),
                         '{"y":[null,"\\u003c\\u0026\\u003d\\u0027\\u2028"]}')
        with self.assertRaises(ValueError):
            crypto.compact_json({"x": float("nan")})

    def test_unverified_native_signature_is_rejected(self):
        with self.assertRaises(ValueError):
            crypto.sign_request("/x", "{}", nonce=NONCE, signature_version=2)
        with self.assertRaises(ValueError):
            crypto.sign_request("/x", "{}", nonce="W" * 32)


if __name__ == "__main__":
    unittest.main()
